html:
{#- Delivery note in the style of the v14 Delivery_Note_CC1, with the driver / AC technician and
    the goods that came back (delivery_management/printing.py). With a Letter Head chosen, Frappe
    prints it above; without one, the company block below is used. -#}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set p = dm_delivery_note_print(doc) -%}
{%- set address = doc.shipping_address or doc.address_display -%}
{%- set status = doc.dm_delivery_status or doc.status -%}
<style>
	.ss-dn { font-size: 11px; color: #000; }
	.ss-dn .ss-company { font-family: serif; font-size: 16px; line-height: 1.25; margin-top: 12px; }
	.ss-dn .ss-logo { width: 70px; }
	.ss-dn .ss-title { text-align: right; margin-top: 18px; }
	.ss-dn .ss-title h2 { font-size: 22px; font-weight: 400; margin: 0; }
	.ss-dn .ss-title .ss-name { color: #888; font-size: 13px; margin-top: 18px; }
	.ss-dn hr { border: 0; border-top: 1px solid #d1d8dd; margin: 8px 0 14px; }
	.ss-dn .ss-info td { padding: 2px 4px; vertical-align: top; }
	.ss-dn .ss-label { font-weight: bold; width: 130px; }
	.ss-dn .ss-table { width: 100%; border-collapse: collapse; margin-top: 18px; }
	.ss-dn .ss-table th { background: #f0f0f0; color: #000; font-weight: bold; text-align: left; }
	.ss-dn .ss-table th, .ss-dn .ss-table td { border: 1px solid #d1d8dd; padding: 5px 6px; vertical-align: top; }
	.ss-dn .ss-table small { color: #555; display: block; }
	.ss-dn .text-right { text-align: right; }
	.ss-dn .ss-returned { color: #c0392b; font-weight: bold; }
	.ss-dn tr.ss-all-back td { color: #888; }
	.ss-dn .ss-tag { border: 1px solid #c0392b; border-radius: 3px; color: #c0392b; font-size: 9px; font-weight: bold;
		padding: 0 4px; text-transform: uppercase; }
	.ss-dn h4 { font-size: 13px; font-weight: bold; margin: 22px 0 0; }
	.ss-dn .ss-totals { width: 50%; margin-left: 50%; margin-top: 8px; }
	.ss-dn .ss-totals td { padding: 4px; vertical-align: top; }
	.ss-dn .ss-totals .ss-label { width: 45%; }
	.ss-dn .ss-grand td { font-weight: bold; font-size: 13px; }
	.ss-dn .ss-sign { margin-top: 26px; width: 100%; }
	.ss-dn .ss-sign td { vertical-align: bottom; width: 50%; }
	.ss-dn .ss-sign img { max-height: 70px; max-width: 220px; display: block; }
	.ss-dn .ss-sign .ss-line { border-top: 1px solid #000; display: inline-block; min-width: 200px; padding-top: 3px; }
	.ss-dn .ss-terms h3 { font-size: 15px; font-weight: bold; margin: 22px 0 12px; }
</style>
<div class="ss-dn">
	{%- if not letter_head %}
	<img class="ss-logo" src="{{ company.company_logo or '/assets/delivery_management/images/show-satellite-logo.png' }}">
	<div class="ss-company">
		Company: {{ company.company_name }}<br>
		{%- if company.tax_id %}VAT NO : {{ company.tax_id }}<br>{% endif %}
		{%- if company.registration_details %}CR: {{ company.registration_details }}{% endif %}
	</div>
	{%- endif %}

	<div class="ss-title">
		<h2>{{ _("RETURN DELIVERY NOTE") if doc.is_return else _("DELIVERY NOTE") }}</h2>
		<div class="ss-name">{{ doc.name }}{% if doc.is_return %} · {{ _("against") }} {{ doc.return_against }}{% endif %}</div>
	</div>
	<hr>

	<table class="ss-info" style="width: 100%">
		<tr>
			<td style="width: 55%">
				<table>
					<tr><td class="ss-label">{{ _("Customer Name") }}:</td><td><b style="font-size: 12px">{{ doc.customer_name }}</b></td></tr>
					<tr><td class="ss-label">{{ _("Mobile No") }}:</td><td>{{ doc.contact_mobile or frappe.db.get_value("Customer", doc.customer, "mobile_no") or "" }}</td></tr>
					{%- if address %}
					<tr><td class="ss-label">{{ _("Shipping Address") }}:</td><td>{{ address }}</td></tr>
					{%- endif %}
				</table>
			</td>
			<td style="width: 45%">
				<table>
					<tr><td class="ss-label">{{ _("Date") }}:</td><td><b style="font-size: 12px">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</b></td></tr>
					<tr><td class="ss-label">{{ _("Status") }}:</td><td>{{ _(status) }}</td></tr>
					{%- if doc.dm_delivery_type %}
					<tr><td class="ss-label">{{ _("Order Type") }}:</td><td>{{ _(doc.dm_delivery_type) }}{% if doc.dm_ac_units %} · {{ doc.dm_ac_units }} {{ _("AC units") }}{% endif %}</td></tr>
					{%- endif %}
					{%- if p.driver %}
					<tr><td class="ss-label">{{ p.driver.label }}:</td><td><b>{{ p.driver.name }}</b></td></tr>
					<tr><td class="ss-label">{{ _("Mobile") }}:</td><td>{{ p.driver.mobile or "" }}</td></tr>
					{%- endif %}
				</table>
			</td>
		</tr>
	</table>

	{%- set any_back = p.rows | selectattr("returned") | list | length %}
	<table class="ss-table">
		<thead>
			<tr>
				<th style="width: 5%">{{ _("Sr") }}</th>
				<th>{{ _("Item") }}</th>
				<th class="text-right" style="width: 10%">{{ _("Quantity") }}</th>
				{%- if any_back %}
				<th class="text-right" style="width: 10%">{{ _("Returned") }}</th>
				<th class="text-right" style="width: 10%">{{ _("Received") }}</th>
				{%- endif %}
				<th class="text-right" style="width: 13%">{{ _("Rate") }}</th>
				<th class="text-right" style="width: 13%">{{ _("Amount") }}</th>
				<th style="width: 13%">{{ _("Warehouse") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for line in p.rows %}
			{%- set row = line.row %}
			<tr class="{{ 'ss-all-back' if line.returned and not line.received }}">
				<td>{{ row.idx }}</td>
				<td>
					{{ row.item_code }}{% if row.item_name != row.item_code %} · {{ row.item_name }}{% endif %}
					{%- if line.returned %} <span class="ss-tag">{{ _("Returned") }}</span>{% endif %}
					{%- if line.serials %}<small>{{ _("Serial No") }}: {{ line.serials | join(", ") }}</small>{% endif %}
				</td>
				<td class="text-right">{{ frappe.format(row.qty | abs, {"fieldtype": "Float"}) }} {{ row.uom }}</td>
				{%- if any_back %}
				<td class="text-right ss-returned">{{ frappe.format(line.returned, {"fieldtype": "Float"}) if line.returned else "" }}</td>
				<td class="text-right"><b>{{ frappe.format(line.received, {"fieldtype": "Float"}) }}</b></td>
				{%- endif %}
				<td class="text-right">{{ row.get_formatted("rate", doc) }}</td>
				<td class="text-right">{{ row.get_formatted("amount", doc) }}</td>
				<td>{{ row.warehouse or "" }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	{%- if p.returned %}
	<h4 class="ss-returned">{{ _("Returned items") }}</h4>
	<table class="ss-table" style="margin-top: 6px">
		<thead>
			<tr>
				<th>{{ _("Item") }}</th>
				<th class="text-right" style="width: 10%">{{ _("Quantity") }}</th>
				<th style="width: 22%">{{ _("Return") }}</th>
				<th style="width: 22%">{{ _("Reason") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for r in p.returned %}
			<tr>
				<td>{{ r.item_code }}{% if r.item_name != r.item_code %} · {{ r.item_name }}{% endif %}
					{%- if r.serials %}<small>{{ _("Serial No") }}: {{ r.serials | join(", ") }}</small>{% endif %}</td>
				<td class="text-right">{{ frappe.format(r.qty, {"fieldtype": "Float"}) }} {{ r.uom }}</td>
				<td>{{ r.note }}<small>{{ frappe.utils.formatdate(r.date, "dd-MM-yyyy") }}</small></td>
				<td>{{ r.reason }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>
	{%- endif %}

	<table class="ss-totals">
		<tr><td class="ss-label">{{ _("Total Quantity") }}:</td><td class="text-right">{{ frappe.format(doc.total_qty | abs, {"fieldtype": "Float"}) }}</td></tr>
		{%- if any_back %}
		<tr><td class="ss-label">{{ _("Received Quantity") }}:</td><td class="text-right"><b>{{ frappe.format(p.rows | sum(attribute="received"), {"fieldtype": "Float"}) }}</b></td></tr>
		{%- endif %}
		<tr><td class="ss-label">{{ _("Total") }}:</td><td class="text-right">{{ doc.get_formatted("total") }}</td></tr>
		<tr><td class="ss-label">{{ _("Total Taxes and Charges") }}:</td><td class="text-right">{{ doc.get_formatted("total_taxes_and_charges") }}</td></tr>
		<tr><td class="ss-label">{{ _("Additional Discount Amount") }}:</td><td class="text-right">{{ doc.get_formatted("discount_amount") }}</td></tr>
		<tr class="ss-grand"><td class="ss-label">{{ _("Grand Total") }}:</td><td class="text-right">{{ doc.get_formatted("grand_total") }}</td></tr>
		<tr><td class="ss-label">{{ _("In Words") }}:</td><td>{{ doc.in_words or "" }}</td></tr>
	</table>

	{%- if not doc.is_return %}
	<table class="ss-sign">
		<tr>
			<td>
				{%- if p.signature %}<img src="{{ p.signature }}">{% endif %}
				<span class="ss-line">{{ _("Customer signature: received the items above") }}{% if any_back %} ({{ _("Received column") }}){% endif %}</span>
			</td>
			<td style="text-align: right">
				<span class="ss-line">{{ p.driver.label if p.driver else _("Driver") }}{% if p.driver %}: {{ p.driver.name }}{% endif %}</span>
			</td>
		</tr>
	</table>
	{%- endif %}

	{%- if doc.terms %}
	<div class="ss-terms">
		<h3>{{ _("Terms & Conditions") }}</h3>
		<div>{{ doc.terms }}</div>
	</div>
	{%- endif %}

	<p style="margin-top: 22px">{{ _("Creator") }}:<br>{{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</p>
	<p style="text-align: center; margin-top: 18px">{{ _("Thank you, please visit again.") }}</p>
</div>
